"""
Git tools for version control operations and change history analysis.

This module provides tools for analyzing git history, changes, and file versions.
Useful for PR reviews, rollback analysis, and forensic change detection.

Made with ❤️ by codx-junior
"""

import os
import logging
from typing import Optional, Union, List

from codx.junior.settings import CODXJuniorSettings
from codx.junior.engine import CODXJuniorSession
from codx.junior.utils.utils import exec_command
from .model import ToolResponse

# Configure logging
logger = logging.getLogger(__name__)

# Constants
DEFAULT_HISTORY_LIMIT = 5
MAX_HISTORY_LIMIT = 20


def _get_git_root_for_file(settings: CODXJuniorSettings, file_path: str) -> Optional[str]:
    """
    Determine the Git root for a given file.

    Args:
        settings: Project settings.
        file_path: The file path (relative or absolute).

    Returns:
        str: The absolute Git root path, or None if not in a git repository.
    """
    if not os.path.isabs(file_path):
        file_path = os.path.join(settings.abs_project_path, file_path)

    current_path = os.path.dirname(file_path)

    while current_path != os.path.dirname(current_path):
        if os.path.exists(os.path.join(current_path, '.git')):
            return current_path
        current_path = os.path.dirname(current_path)

    return None


def _to_relative_path(settings: CODXJuniorSettings, abs_path: str) -> str:
    """
    Convert an absolute file path to a relative path within the project.

    Args:
        settings: The project settings.
        abs_path: Absolute path to convert.

    Returns:
        str: Relative path from project root.
    """
    if abs_path.startswith(settings.abs_project_path):
        rel_path = os.path.relpath(abs_path, settings.abs_project_path)
        return rel_path
    return abs_path


def get_file_history(
    file_path: str,
    limit: int = DEFAULT_HISTORY_LIMIT,
    show_diff: bool = True,
    **kwargs
) -> ToolResponse:
    """
    Retrieve the git history of a file with optional diff details for each commit.

    This tool helps analyze how a file has changed over time by showing:
    - Recent commits that modified the file
    - Diff details for each commit
    - Author and date information
    - File status changes (added, modified, deleted)

    Useful for PR reviews, understanding breaking changes, and rollback analysis.

    Args:
        file_path: Relative or absolute path to the file to analyze.
        limit: Maximum number of commits to retrieve (1-20, default: 5).
               Increase for deeper history analysis.
        show_diff: If True, includes diff details for each commit (default: True).
        **kwargs: Additional arguments including:
            - settings (CODXJuniorSettings): Project settings (required).

    Returns:
        ToolResponse: Contains:
            - user_response: Summary of commits found.
            - llm_response: Formatted history with commits and diffs (if enabled).

    Raises:
        Exception: If project settings are not provided or file is not in git.

    Example:
        Get last 5 commits for a file with diffs:
        >>> get_file_history("src/main.py", limit=5, show_diff=True)

        Get last 10 commits without diffs:
        >>> get_file_history("config/settings.py", limit=10, show_diff=False)
    """
    settings: CODXJuniorSettings = kwargs.get("settings", None)
    if not settings:
        raise Exception("Invalid project settings")

    if not file_path:
        raise ValueError("file_path must be provided and cannot be empty")

    # Normalize limit
    limit = max(1, min(int(limit), MAX_HISTORY_LIMIT))

    # Resolve absolute path
    if not os.path.isabs(file_path):
        abs_path = os.path.join(settings.abs_project_path, file_path)
    else:
        abs_path = file_path

    # Verify file exists
    if not os.path.isfile(abs_path):
        error_msg = f"File not found: {file_path}"
        logger.warning(error_msg)
        return ToolResponse(
            user_response=f"error [{file_path}]\nERROR: {error_msg}",
            llm_response=f"Failed to retrieve file history: {error_msg}",
        )

    # Check if file is in a git repository
    git_root = _get_git_root_for_file(settings=settings, file_path=abs_path)
    if not git_root:
        error_msg = f"File is not in a git repository: {file_path}"
        logger.warning(error_msg)
        return ToolResponse(
            user_response=f"error [{file_path}]\nERROR: {error_msg}",
            llm_response=f"Failed to retrieve file history: {error_msg}",
        )

    # Get relative path from git root
    rel_path_from_git = os.path.relpath(abs_path, git_root)

    try:
        # Get commit history
        pretty_format = "%H|%an|%ae|%ad|%s"
        log_cmd = f"git log --pretty=format:{pretty_format} --date=short -n {limit} -- {rel_path_from_git}"

        stdout, stderr = exec_command(log_cmd, cwd=git_root)

        if stderr and "fatal" in stderr.lower():
            error_msg = f"Failed to retrieve git history: {stderr}"
            logger.error(error_msg)
            return ToolResponse(
                user_response=f"error [{file_path}]\nERROR: {error_msg}",
                llm_response=f"Failed to retrieve file history: {error_msg}",
            )

        if not stdout.strip():
            info_msg = f"No git history found for file: {file_path}"
            logger.info(info_msg)
            return ToolResponse(
                user_response=f"No commits found for: {file_path}",
                llm_response=f"File has no git history: {file_path}",
            )

        # Parse commits
        commits = []
        commit_lines = stdout.strip().split("\n")

        for line in commit_lines:
            if not line.strip():
                continue
            try:
                commit_hash, author_name, author_email, date, message = line.split("|", 4)
                commits.append({
                    "hash": commit_hash[:8],
                    "full_hash": commit_hash,
                    "author": author_name,
                    "email": author_email,
                    "date": date,
                    "message": message.strip(),
                })
            except ValueError as e:
                logger.warning("Could not parse commit line: %s", line)
                continue

        if not commits:
            info_msg = f"No valid commits found for file: {file_path}"
            logger.info(info_msg)
            return ToolResponse(
                user_response=f"No valid commits found for: {file_path}",
                llm_response=f"File has no valid git history: {file_path}",
            )

        # Build history output
        history_output = [
            f"# File History: {file_path}",
            f"Total commits found: {len(commits)}\n",
        ]

        # Add commits and diffs
        for i, commit in enumerate(commits, 1):
            history_output.append(f"## Commit {i}/{len(commits)}")
            history_output.append(f"- Hash: `{commit['hash']}` ({commit['full_hash']})")
            history_output.append(f"- Author: {commit['author']} <{commit['email']}>")
            history_output.append(f"- Date: {commit['date']}")
            history_output.append(f"- Message: {commit['message']}\n")

            # Add diff if requested
            if show_diff:
                try:
                    # Get diff for this commit
                    diff_cmd = f"git show {commit['full_hash']}:{rel_path_from_git}"
                    diff_stdout, diff_stderr = exec_command(diff_cmd, cwd=git_root)

                    if diff_stderr and "fatal" not in diff_stderr.lower():
                        history_output.append("```diff")
                        history_output.append(diff_stdout[:500])  # Limit diff size
                        if len(diff_stdout) > 500:
                            history_output.append("... (truncated)")
                        history_output.append("```\n")
                    elif not diff_stderr:
                        history_output.append("```diff")
                        history_output.append(diff_stdout[:500])  # Limit diff size
                        if len(diff_stdout) > 500:
                            history_output.append("... (truncated)")
                        history_output.append("```\n")

                except Exception as e:
                    logger.debug("Could not retrieve diff for commit %s: %s", commit['hash'], str(e))

        llm_response = "\n".join(history_output)

        # Build summary for user response
        user_response = (
            f"Retrieved history for: `{file_path}` | "
            f"Commits: {len(commits)} | "
            f"Diffs: {'included' if show_diff else 'excluded'}"
        )

        logger.info("Retrieved file history: %s (%d commits)", file_path, len(commits))
        return ToolResponse(user_response=user_response, llm_response=llm_response)

    except Exception as e:
        error_msg = f"Error retrieving file history: {str(e)}"
        logger.error(error_msg)
        return ToolResponse(
            user_response=f"error [{file_path}]\nERROR: {error_msg}",
            llm_response=f"Failed to retrieve file history: {error_msg}",
        )

